# =============================
# Utilities (parsers)
# =============================


def _clean_text(s: Optional[str]) -> str:
    return re.sub(r'\s+', ' ', (s or '').strip())


def _normalize_correct_answer(s: str) -> str:
    """Normalize answers like 'A', 'A)', 'Correct: A', etc. to a single letter A-D."""
    s = _clean_text(s)
    m = re.search(r'\b([A-Da-d])\s*[\)\].]?\b', s)
    return m.group(1).upper() if m else s


def parse_story_and_questions(raw: str) -> dict:
    """
    Parse a single story + questions blob created by the generator into:
    {
      'story': str,
      'questions': [
          {'id': str, 'text': str, 'answers': [A,B,C,D], 'correct_answer': 'A'-'D', 'source': str}
      ]
    }
    """
    import xml.etree.ElementTree as ET

    wrapped = f'<root>{raw}</root>'
    root = ET.fromstring(wrapped)

    story_el = root.find('story')
    story = _clean_text(story_el.text if story_el is not None else '')

    questions_el = root.find('questions')
    questions: list[dict] = []
    if questions_el is not None:
        for q in questions_el.findall('question'):
            qid = q.attrib.get('id', '')

            qtext_el = q.find('text')
            qtext = _clean_text(qtext_el.text if qtext_el is not None else '')

            answers: list[str] = []
            for i in range(1, 5):
                a_el = q.find(f'answer{i}')
                if a_el is not None and (a_el.text or '').strip():
                    answers.append(_clean_text(a_el.text))

            ca_el = q.find('correct_answer')
            correct_answer = _normalize_correct_answer(
                ca_el.text if ca_el is not None else ''
            )

            src_el = q.find('source')
            source = _clean_text(src_el.text if src_el is not None else '')

            questions.append(
                {
                    'id': qid,
                    'text': qtext,
                    'answers': answers,
                    'correct_answer': correct_answer,
                    'source': source,
                }
            )

    return {'story': story, 'questions': questions}


def parse_llm_answers(
    output_text: str, question_answers: list[dict]
) -> dict[str, Optional[str]]:
    """
    Returns {question_id: 'A'|'B'|'C'|'D' or None}.
    Priority:
      1) Compact <answers> block with lines: "<id>=<A/B/C/D>"
      2) Full blocks with ID + 'YOUR ANSWER: X'
      3) Bare 'YOUR ANSWER: X' lines mapped by order
    """
    text = (output_text or '').replace('\r\n', '\n').replace('\r', '\n')
    ids_in_order = [q['id'] for q in question_answers]

    # 1) Compact <answers> block
    m = re.search(
        r'<answers>\s*(.*?)\s*</answers>', text, flags=re.DOTALL | re.IGNORECASE
    )
    block = m.group(1) if m else text
    pairs = re.findall(
        r'^\s*([0-9A-Za-z_-]+)\s*=\s*([ABCD])\s*$',
        block,
        flags=re.MULTILINE | re.IGNORECASE,
    )
    ans_map = {qid: ans.upper() for qid, ans in pairs}

    if not ans_map:
        pairs2 = re.findall(
            r'^\s*(?:Question\s*ID:\s*)?([0-9A-Za-z_-]+)\s*[:=]\s*(?:Answer:\s*)?([ABCD])\s*$',
            block,
            flags=re.MULTILINE | re.IGNORECASE,
        )
        ans_map = {qid: ans.upper() for qid, ans in pairs2}

    if len(ans_map) == len(ids_in_order) and len(ids_in_order) > 0:
        return ans_map

    # 2) Full block parsing
    blocks = re.split(r'^\s*=== QUESTION ===\s*$', text, flags=re.MULTILINE)
    for blk in blocks:
        if not blk.strip():
            continue
        blk = re.split(r'^\s*=== END ===\s*$', blk, maxsplit=1, flags=re.MULTILINE)[0]
        m_id = re.search(r'^\s*ID:\s*(.+?)\s*$', blk, flags=re.MULTILINE)
        m_ans = re.search(
                r'^\s*YOUR ANSWER:\s*([ABCD])\s*(?:[).:])?\s*$',
                blk,
                flags=re.IGNORECASE | re.MULTILINE,
            )
        if m_id and m_ans:
            qid = m_id.group(1).strip()
            ans_map[qid] = m_ans.group(1).upper()

    if len(ans_map) == len(ids_in_order) and len(ids_in_order) > 0:
        return ans_map

    # 3) Bare YOUR ANSWER lines
    letters = re.findall(
        r'YOUR ANSWER:\s*([ABCD])\s*(?:[).:])?', text, flags=re.IGNORECASE
    )
    letters = [x.upper() for x in letters]

    filled: dict[str, Optional[str]] = {}
    for qid in ids_in_order:
        filled[qid] = ans_map.get(qid)

    li = 0
    for qid in ids_in_order:
        if filled[qid] is None:
            if li < len(letters):
                filled[qid] = letters[li]
                li += 1
            else:
                filled[qid] = None

    return filled


# =============================
# Data loading and aggregation
# =============================


@st.cache_data(show_spinner=False)
def find_available_runs(root: str) -> list[Path]:
    root_path = Path(root).expanduser().resolve()
    if not root_path.exists():
        return []
    # Look for any performance.json within a few levels
    candidates = list(root_path.rglob('results.csv'))
    # Sort by modified time (newest first)
    candidates.sort(key=lambda p: p.stat().st_mtime, reverse=True)
    return [c.parent for c in candidates]


def read_yaml_safe(path: Path) -> Optional[dict]:
    try:
        import yaml

        with open(path, 'r') as f:
            return yaml.safe_load(f) or {}
    except Exception:
        return None


@st.cache_data(show_spinner=False)
def load_run(path: Path) -> dict:
    """
    Load a single run folder (the directory that contains performance.json and the story/prompt/reply files).
    Returns a dict with:
        'path', 'config', 'performance', 'stories', 'prompts', 'replies', 'rows'
    where 'rows' is a per-question dataframe-able list of dicts.
    """
    path = Path(path)
    perf_path = path / 'results.csv'
    df = pd.read_csv(perf_path)
    performance = df["accuracy"].mean()
    # if not perf_path.exists():
    #     raise FileNotFoundError(f'Missing results.csv in {path}')

    # with open(perf_path, 'r') as f:
    #     performance = json.load(f)


    cfg_path = path / '.hydra' / 'config.yaml'
    cfg = read_yaml_safe(cfg_path) if cfg_path.exists() else None

    # Collect story files
    story_files = sorted(
        path.glob('story_questions_*.txt'),
        key=lambda p: int(re.search(r'(\d+)', p.stem).group(1)),
    )
    prompt_files = sorted(
        path.glob('prompt_*.txt'),
        key=lambda p: int(re.search(r'(\d+)', p.stem).group(1)),
    )
    reply_files = sorted(
        path.glob('llm_reply_*.txt'),
        key=lambda p: int(re.search(r'(\d+)', p.stem).group(1)),
    )

    parsed_stories = []
    for sf in story_files:
        try:
            parsed = parse_story_and_questions(sf.read_text())
            parsed_stories.append(parsed)
        except Exception as e:
            parsed_stories.append({'story': f'[Parse error: {e}]', 'questions': []})

    prompts = [pf.read_text() for pf in prompt_files]
    replies = [rf.read_text() for rf in reply_files]

    n = len(parsed_stories)
    rows: list[dict] = []

    for i in range(n):
        story_i = parsed_stories[i]
        # Questions come from the NEXT story (wrap around)
        j = (i + 1) % n
        q_story = parsed_stories[j]
        q_list = q_story.get('questions', [])

        # LLM replies for i-th prompt
        llm_text = replies[i] if i < len(replies) else ''
        llm_map = parse_llm_answers(llm_text, q_list)

        for q in q_list:
            qid = q.get('id')
            answers = q.get('answers', [])
            # Normalize options to exactly 4 columns
            opts = {k: None for k in ['A', 'B', 'C', 'D']}
            labels = ['A', 'B', 'C', 'D']
            for lab, opt in zip(labels, answers[:4]):
                opt_clean = opt.strip()
                # strip leading "A) " etc.
                if opt_clean.startswith(f'{lab}) '):
                    opt_clean = opt_clean[len(f'{lab}) ') :]
                opts[lab] = opt_clean

            correct = _normalize_correct_answer(q.get('correct_answer', ''))
            llm_ans = (llm_map or {}).get(qid)

            rows.append(
                {
                    'run_path': str(path),
                    'story_idx': i,
                    'question_from_story_idx': j,
                    'question_id': qid,
                    'question_text': q.get('text'),
                    'option_A': opts['A'],
                    'option_B': opts['B'],
                    'option_C': opts['C'],
                    'option_D': opts['D'],
                    'correct_answer': correct,
                    'llm_answer': llm_ans,
                    'is_correct': (llm_ans == correct) if llm_ans is not None else None,
                    'source': q.get('source'),
                    'story_text': story_i.get('story'),
                    'prompt_text': prompts[i] if i < len(prompts) else '',
                    'llm_reply': llm_text,
                }
            )

    data = {
        'path': str(path),
        'config': cfg,
        'performance': performance,
        'stories': parsed_stories,
        'prompts': prompts,
        'replies': replies,
        'rows': rows,
    }
    return data


def compute_overall_metrics(df: pd.DataFrame) -> dict[str, float]:
    if df.empty:
        return {'total_questions': 0, 'answered': 0, 'correct': 0, 'accuracy': 0.0}
    answered = df['llm_answer'].notna().sum()
    correct = df['is_correct'].fillna(False).sum()
    total = len(df)
    acc = (correct / total) if total else 0.0
    return {
        'total_questions': int(total),
        'answered': int(answered),
        'correct': int(correct),
        'accuracy': float(acc),
    }


def confusion_matrix(df: pd.DataFrame) -> pd.DataFrame:
    letters = list('ABCD')
    mat = pd.DataFrame(
        0, index=pd.Index(letters, name='True'), columns=pd.Index(letters, name='Pred')
    )
    sub = df.dropna(subset=['llm_answer', 'correct_answer'])  # only answered
    for _, row in sub.iterrows():
        t = row['correct_answer']
        p = row['llm_answer']
        if t in letters and p in letters:
            mat.loc[t, p] += 1
    return mat


# =============================
# Sidebar: path + run selection
# =============================
DEFAULT_ROOT = '/home/tommaso/repo/OpenHands/bias_check/outputs'
root_dir = st.sidebar.text_input('Root outputs directory', value=DEFAULT_ROOT)

runs = find_available_runs(root_dir)

if not runs:
    st.sidebar.warning(
        'No runs found. Make sure the path points to a directory that contains your generated outputs.'
    )
else:
    run_labels = [
        f'{r.parent.name}/{r.name}' for r in runs
    ]  # show parent folder + model folder
    selected = st.sidebar.selectbox(
        'Select a run',
        options=list(range(len(runs))),
        format_func=lambda i: run_labels[i],
    )
    selected_run = runs[selected]

    data = load_run(selected_run)
    rows_df = (
        pd.DataFrame(data['rows'])
        if data['rows']
        else pd.DataFrame(
            columns=[
                'story_idx',
                'question_from_story_idx',
                'question_id',
                'question_text',
                'option_A',
                'option_B',
                'option_C',
                'option_D',
                'correct_answer',
                'llm_answer',
                'is_correct',
                'source',
                'story_text',
                'prompt_text',
                'llm_reply',
                'run_path',
            ]
        )
    )

    # =============================
    # Overview / Metrics
    # =============================
    st.subheader('Overview')

    col1, col2, col3, col4 = st.columns(4)

    m = compute_overall_metrics(rows_df)
    col1.metric('Total questions', m['total_questions'])
    col2.metric('Answered', m['answered'])
    col3.metric('Correct', m['correct'])
    col4.metric('Accuracy', f'{m["accuracy"] * 100:.1f}%')

    if isinstance(data.get('performance'), list) and data['performance']:
        # The last entry may be {'average_accuracy': x}
        avg_acc = None
        for entry in data['performance']:
            if isinstance(entry, dict) and 'average_accuracy' in entry:
                avg_acc = entry['average_accuracy']
        if avg_acc is not None:
            st.caption(f'Average accuracy from pipeline: **{avg_acc * 100:.1f}%**')

    # Accuracy by story
    if not rows_df.empty:
        by_story = (
            rows_df.groupby('story_idx')['is_correct']
            .mean()
            .reset_index()
            .rename(columns={'is_correct': 'accuracy'})
        )
        st.bar_chart(by_story.set_index('story_idx'))

    # =============================
    # Filters
    # =============================
    with st.expander('Filters', expanded=False):
        cols = st.columns(3)
        story_filter = cols[0].multiselect(
            'Story index',
            options=sorted(rows_df['story_idx'].unique()),
            default=sorted(rows_df['story_idx'].unique()),
        )
        correctness_filter = cols[1].multiselect(
            'Correctness',
            options=['Correct', 'Incorrect', 'Unanswered'],
            default=['Correct', 'Incorrect', 'Unanswered'],
        )
        query = cols[2].text_input('Search in question text/source')

    def apply_filters(df: pd.DataFrame) -> pd.DataFrame:
        if df.empty:
            return df
        mask = df['story_idx'].isin(story_filter)
        if 'Correct' not in correctness_filter:
            mask &= ~(df['is_correct'])
        if 'Incorrect' not in correctness_filter:
            mask &= ~(not df['is_correct'])
        if 'Unanswered' not in correctness_filter:
            mask &= ~(df['llm_answer'].isna())
        if query:
            q = query.lower()
            mask &= df['question_text'].fillna('').str.lower().str.contains(q) | df[
                'source'
            ].fillna('').str.lower().str.contains(q)
        return df[mask]

    filtered = apply_filters(rows_df)

    # =============================
    # Per-question table
    # =============================
    st.subheader('Per-question results')

    if filtered.empty:
        st.info('No rows match the current filters.')
    else:
        show_cols = [
            'story_idx',
            'question_from_story_idx',
            'question_id',
            'question_text',
            'option_A',
            'option_B',
            'option_C',
            'option_D',
            'correct_answer',
            'llm_answer',
            'is_correct',
            'source',
        ]
        st.dataframe(
            filtered[show_cols].reset_index(drop=True),
            use_container_width=True,
            hide_index=True,
        )

        # Download CSV
        csv = filtered.to_csv(index=False).encode('utf-8')
        st.download_button(
            'Download filtered CSV',
            data=csv,
            file_name='results_filtered.csv',
            mime='text/csv',
        )

    # =============================
    # Confusion matrix
    # =============================
    st.subheader('Confusion matrix (True vs Pred)')
    cm = confusion_matrix(filtered)
    st.dataframe(cm, use_container_width=True)

    # =============================
    # Drill-down: Story, Prompt, Reply
    # =============================
    st.subheader('Drill-down')
    sel_story = st.number_input(
        'Select story index',
        min_value=0,
        max_value=max(rows_df['story_idx']) if not rows_df.empty else 0,
        value=0,
        step=1,
    )

    if not rows_df.empty:
        story_block = rows_df[rows_df['story_idx'] == sel_story].iloc[0]
        with st.expander('Story text', expanded=False):
            st.write(story_block['story_text'])  # already plain text
        with st.expander('Prompt sent to LLM', expanded=False):
            st.code(story_block['prompt_text'], language='text')
        with st.expander('LLM reply (raw)', expanded=False):
            st.code(story_block['llm_reply'], language='text')

        # Show the set of questions used for this story
        st.markdown(
            '**Questions used for this story** (come from the *next* story file in the run)'
        )
        sub = rows_df[rows_df['story_idx'] == sel_story][
            [
                'question_id',
                'question_text',
                'option_A',
                'option_B',
                'option_C',
                'option_D',
                'correct_answer',
                'llm_answer',
                'is_correct',
                'source',
            ]
        ].reset_index(drop=True)
        st.dataframe(sub, use_container_width=True)

    # =============================
    # Config view
    # =============================
    st.subheader('Run configuration (.hydra/config.yaml)')
    cfg = data.get('config')
    if cfg:
        st.json(cfg)
    else:
        st.caption('No config found or unable to parse YAML.')

st.markdown('---')
st.caption(
    "Tip: Point the sidebar path at your outputs directory (it should contain subfolders with 'performance.json'). The app automatically discovers runs and builds the tables and charts."
)
